<?php require '_layout.php'; $pdo=db(); $items=[]; if($pdo) try{$items=$pdo->query('SELECT * FROM products ORDER BY featured DESC,id DESC')->fetchAll(PDO::FETCH_ASSOC);}catch(Throwable $e){} admin_header('Sản phẩm','products'); admin_flash(); ?>
<section class="products-admin"><div class="dashboard-actions"><div><div class="kicker">Catalogue</div><h2>Quản lý sản phẩm</h2><p>Cập nhật nội dung, giá, ảnh và trạng thái giao hàng trên website.</p></div><a class="admin-button" href="product-form.php">+ Thêm sản phẩm</a></div><div class="toolbar"><label class="search"><span>⌕</span><input type="search" placeholder="Tìm tên sản phẩm..." data-product-search></label><div><button class="filter active" data-filter="all">Tất cả</button><button class="filter" data-filter="fast">Giao nhanh</button><button class="filter" data-filter="hidden">Đang ẩn</button></div></div><?php if(!$pdo): ?><div class="notice error">MySQL chưa kết nối nên chưa thể quản lý sản phẩm. Import <code>database.sql</code> trước.</div><?php elseif(!$items): ?><div class="empty"><div>□</div><h3>Chưa có sản phẩm</h3><p>Hãy tạo sản phẩm đầu tiên để hiển thị trên website.</p><a class="admin-button" href="product-form.php">+ Thêm sản phẩm</a></div><?php else: ?><div class="product-table"><div class="table-row table-head"><span>Sản phẩm</span><span>Giá niêm yết</span><span>Trạng thái giao</span><span>Hiển thị</span><span></span></div><?php foreach($items as $item): ?><article class="table-row" data-product-row data-name="<?=htmlspecialchars(mb_strtolower($item['name']))?>" data-fast="<?=$item['fast']?>" data-active="<?=$item['active']?>"><div class="admin-product"><img src="<?=htmlspecialchars($item['image'])?>" alt=""><div><b><?=htmlspecialchars($item['name'])?></b><small><?=htmlspecialchars($item['type'])?></small></div></div><strong><?=number_format($item['price'],0,',','.')?>đ</strong><span><i class="delivery <?=$item['fast']?'':'order'?>"></i><?=$item['fast']?'Giao nhanh 2–3 ngày':htmlspecialchars($item['status'])?></span><span class="visibility <?=$item['active']?'visible':'hidden'?>"><?=$item['active']?'Đang hiển thị':'Đang ẩn'?></span><div class="table-actions"><a href="product-form.php?id=<?=$item['id']?>">Sửa</a><form method="post" action="product-delete.php" onsubmit="return confirm('Xoá sản phẩm này?')"><input type="hidden" name="id" value="<?=$item['id']?>"><button>Xoá</button></form></div></article><?php endforeach ?></div><?php endif ?></section><?php admin_footer(); ?>
